import io,gzip,base64,zipfile
import pandas as pd,streamlit as st
st.set_page_config(page_title="V6.19 Geometri Once",page_icon="🧭",layout="wide")
st.title("🧭 V6.19 — GEOMETRİ ÖNCE PROFESÖRÜ")
st.success("152 doğru-hareket ateşleme çekilişi. Pair seçimi yok.")
DATA=""""""
def load(): return pd.read_csv(io.BytesIO(gzip.decompress(base64.b64decode(DATA))))
d=load().sort_values("draw_no").reset_index(drop=True)
if len(d)!=152 or d.draw_no.nunique()!=152:
 st.error(f"Kapsam hatası: {len(d)}/{d.draw_no.nunique()}"); st.stop()
# only PRE-H columns form the signature
d["sig"]=d["pre_regime"].astype(str)+"|"+d["phase"].astype(str)+"|"+d["H1_shape"].astype(str)+"|"+d["block_count_delta_21"].astype(str)+"|"+d["max_len_delta_21"].astype(str)
draws=sorted(d.draw_no.unique()); warm=50; rows=[]
for i in range(warm,len(draws)):
 t=draws[i]; tr=d[d.draw_no<t]; x=d[d.draw_no==t].iloc[0]
 same=tr[tr.sig==x.sig]
 if len(same)<3: same=tr[(tr.H1_shape==x.H1_shape)&(tr.pre_regime==x.pre_regime)]
 if len(same)<3: same=tr[tr.H1_shape==x.H1_shape]
 if len(same)<3: same=tr
 m=same.groupby(["H_block_count","H_max_len","H_shape"]).size().reset_index(name="n").sort_values(["n","H_block_count","H_max_len"],ascending=[False,True,True]).iloc[0]
 rows.append({"draw_no":int(t),"pred_count":int(m.H_block_count),"actual_count":int(x.H_block_count),
 "pred_maxlen":int(m.H_max_len),"actual_maxlen":int(x.H_max_len),"pred_shape":m.H_shape,"actual_shape":x.H_shape,
 "count_hit":int(m.H_block_count==x.H_block_count),"maxlen_hit":int(m.H_max_len==x.H_max_len),
 "shape_hit":int(str(m.H_shape)==str(x.H_shape)),"history_matches":len(same)})
r=pd.DataFrame(rows)
s=pd.DataFrame([{"test_draws":len(r),"count_hits":int(r.count_hit.sum()),"count_rate":r.count_hit.mean(),
"maxlen_hits":int(r.maxlen_hit.sum()),"maxlen_rate":r.maxlen_hit.mean(),"exact_shape_hits":int(r.shape_hit.sum()),"exact_shape_rate":r.shape_hit.mean()}])
st.dataframe(s,use_container_width=True,hide_index=True)
st.dataframe(r,use_container_width=True,hide_index=True)
bio=io.BytesIO()
with zipfile.ZipFile(bio,"w",zipfile.ZIP_DEFLATED) as z:
 z.writestr("01_SUMMARY.csv",s.to_csv(index=False).encode("utf-8-sig"))
 z.writestr("02_GEOMETRY_WF.csv",r.to_csv(index=False).encode("utf-8-sig"))
st.download_button("⬇️ V6.19 TEK ZIP",bio.getvalue(),"HIZLI_ON_V6_19_GEOMETRI_ONCE.zip","application/zip",use_container_width=True)
